import java.util.Map;

public class SolutionTest {
    public static void main(String[] args) {
        assertMapEquals(mapOf(), Solution.summarizeInspections(null), "null input");
        assertMapEquals(mapOf(), Solution.summarizeInspections(new String[0]), "empty input");

        String[] records = {
            "V1;true;false;true",
            "V2;false;true;false",
            "V1;false;true;true",
            "V1;true;false;false",
            "V2;true;true;true"
        };
        Map<String, String> expected = mapOf(
            "V1", "2,1,2",
            "V2", "1,2,1"
        );
        assertMapEquals(expected, Solution.summarizeInspections(records), "normal aggregation");

        String[] malformed = {
            null,
            "",
            ";true;false;true",
            "V3;true;false",
            "V3;true;false;true;extra",
            "V3;True;false;true",
            "V3;false;FALSE;true",
            "V3;false;true;yes",
            "V3;;false;true",
            "V3;true;false;",
            "V3; true;false;true",
            " V4;true;false;false",
            "V5;false;false;false"
        };
        assertMapEquals(mapOf(
            " V4", "1,0,0",
            "V5", "0,0,0"
        ), Solution.summarizeInspections(malformed), "malformed records and exact text rules");

        String[] allCombinations = {
            "A;true;true;true",
            "A;false;false;false",
            "B;true;false;false",
            "B;false;true;false",
            "B;false;false;true"
        };
        String[] snapshot = allCombinations.clone();
        Map<String, String> first = Solution.summarizeInspections(allCombinations);
        assertArrayEquals(snapshot, allCombinations, "input must not be modified");
        assertMapEquals(mapOf("A", "1,1,1", "B", "1,1,1"), first, "boolean boundaries");

        first.put("injected", "9,9,9");
        Map<String, String> second = Solution.summarizeInspections(allCombinations);
        assertMapEquals(mapOf("A", "1,1,1", "B", "1,1,1"), second,
            "later calls must be independent of a prior returned map");
    }

    private static Map<String, String> mapOf(String... entries) {
        Map<String, String> map = new LinkedHashMap<>();
        for (int i = 0; i < entries.length; i += 2) {
            map.put(entries[i], entries[i + 1]);
        }
        return map;
    }

    private static void assertMapEquals(Map<String, String> expected,
                                        Map<String, String> actual,
                                        String message) {
        if (actual == null || !expected.equals(actual)) {
            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
        }
    }

    private static void assertArrayEquals(String[] expected, String[] actual, String message) {
        if (expected.length != actual.length) {
            throw new AssertionError(message + ": array length changed");
        }
        for (int i = 0; i < expected.length; i++) {
            if (expected[i] == null ? actual[i] != null : !expected[i].equals(actual[i])) {
                throw new AssertionError(message + ": difference at index " + i);
            }
        }
    }
}
