        int[] emptySecond = Solution.decodeReadings(new byte[0]);
        assertIntArrayEquals(new int[0], emptyFirst, "empty input");
        if (emptyFirst == emptySecond) {
            throw new AssertionError("each empty invocation must return a fresh array");
        }

        byte[] packed = {
            (byte) 0x00, (byte) 0x00,
            (byte) 0x3F, (byte) 0xFF,
            (byte) 0xA0, (byte) 0x01,
            (byte) 0xFF, (byte) 0xFF
        };
        byte[] snapshot = packed.clone();
        int[] decoded = Solution.decodeReadings(packed);
        assertIntArrayEquals(new int[] {
            0, 0,
            1, 8191,
            5, 1,
            7, 8191
        }, decoded, "boundary IDs and readings");
        assertByteArrayEquals(snapshot, packed, "input must not be modified");

        assertIntArrayEquals(new int[] {
            0, 255,
            3, 256,
            6, 4266
        }, Solution.decodeReadings(new byte[] {
            (byte) 0x00, (byte) 0xFF,
            (byte) 0x61, (byte) 0x00,
            (byte) 0xD0, (byte) 0xAA
        }), "bytes must be interpreted as unsigned bit patterns");

