        assertIntArrayEquals(new int[] {1, 291}, second,
            "mutating the input after return must not affect an existing result");
        assertIntArrayEquals(new int[] {7, 8191}, Solution.decodeReadings(isolatedInput),
            "a later call must decode the input's current contents independently");
    }

