{"items":[{"id":"cap-v2-binary_and_bitwise-java-generation-02","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testEmptyInput();
        testSingleReadingAndPadding();
        testDensePackingAcrossBoundaries();
        testBoundaryValues();
        testInputIsNotMutated();
        testInvocationIsolation();
    }

    private static void testEmptyInput() {
        byte[] first = Solution.packReadings(new int[0]);
        byte[] second = Solution.packReadings(new int[0]);
        assertEquals(0, first.length, "empty output length");
        assertTrue(first != second, "empty invocations must return newly allocated arrays");
    }

    private static void testSingleReadingAndPadding() {
        assertBytes(new int[] {0xABC}, new int[] {0xAB, 0xC0}, "single reading");
        assertBytes(new int[] {0}, new int[] {0x00, 0x00}, "single zero");
        assertBytes(new int[] {1}, new int[] {0x00, 0x10}, "unused low bits must be zero");
    }

    private static void testDensePackingAcrossBoundaries() {
        assertBytes(new int[] {0xABC, 0x123}, new int[] {0xAB, 0xC1, 0x23}, "two readings");
        assertBytes(new int[] {1, 2}, new int[] {0x00, 0x10, 0x02}, "leading zero bits");
        assertBytes(new int[] {0xFFF, 0, 1}, new int[] {0xFF, 0xF0, 0x00, 0x00, 0x10}, "odd reading count");
    }

    private static void testBoundaryValues() {
        assertBytes(new int[] {0, 0xFFF}, new int[] {0x00, 0x0F, 0xFF}, "minimum and maximum");
        assertBytes(new int[] {0xFFF, 0xFFF}, new int[] {0xFF, 0xFF, 0xFF}, "all bits set");
    }

    private static void testInputIsNotMutated() {
        int[] readings = {0x123, 0x456, 0x789};
        int[] original = readings.clone();
        Solution.packReadings(readings);
        assertTrue(Arrays.equals(original, readings), "input readings were mutated");
    }

    private static void testInvocationIsolation() {
        int[] readings = {0xABC, 0x123};
        byte[] first = Solution.packReadings(readings);
        first[0] = 0;

        byte[] second = Solution.packReadings(readings);
        assertUnsignedBytes(second, new int[] {0xAB, 0xC1, 0x23}, "later invocation depends on earlier output mutation");
        assertTrue(first != second, "invocations returned the same array");

        byte[] other = Solution.packReadings(new int[] {0});
        other[0] = 99;
        assertUnsignedBytes(second, new int[] {0xAB, 0xC1, 0x23}, "later output changed an earlier output");
    }

    private static void assertBytes(int[] input, int[] expected, String message) {
        assertUnsignedBytes(Solution.packReadings(input), expected, message);
    }

    private static void assertUnsignedBytes(byte[] actual, int[] expected, String message) {
        assertEquals(expected.length, actual.length, message + " length");
        for (int i = 0; i < expected.length; i++) {
            int value = actual[i] & 0xFF;
            if (value != expected[i]) {
                throw new AssertionError(message + " at byte " + i + ": expected " + expected[i] + " but was " + value);
            }
        }
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + ": expected " + expected + " but was " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
"},{"id":"cap-v2-binary_and_bitwise-java-repair-01","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testEmptyOperations();
        testSeparatedDuplicateIsIgnored();
        testSetAndClearAreDistinctOperations();
        testAllBitPositions();
        testSignBit();
        testInputIsNotMutated();
        testStableIndependentInvocations();
    }

    private static void testEmptyOperations() {
        assertEquals(0x13579BDF, Solution.applyUniqueOperations(0x13579BDF, new int[0]), "empty operations");
    }

    private static void testSeparatedDuplicateIsIgnored() {
        int result = Solution.applyUniqueOperations(0, new int[] {33, 1, 33});
        assertEquals(0, result, "non-adjacent duplicate set operation must be ignored");

        result = Solution.applyUniqueOperations(-1, new int[] {5, 37, 5});
        assertEquals(-33, result, "non-adjacent duplicate clear operation must be ignored");
    }

    private static void testSetAndClearAreDistinctOperations() {
        int result = Solution.applyUniqueOperations(0, new int[] {32, 0, 32, 0});
        assertEquals(0, result, "encoded set and clear operations must each run once");

        result = Solution.applyUniqueOperations(0, new int[] {35, 35, 3, 35, 3});
        assertEquals(0, result, "adjacent and separated duplicates");
    }

    private static void testAllBitPositions() {
        int[] clearThenSet = new int[64];
        for (int i = 0; i < 64; i++) {
            clearThenSet[i] = i;
        }
        assertEquals(-1, Solution.applyUniqueOperations(0, clearThenSet), "all clear operations followed by all set operations");

        int[] setThenClear = new int[64];
        for (int i = 0; i < 32; i++) {
            setThenClear[i] = 63 - i;
            setThenClear[32 + i] = 31 - i;
        }
        assertEquals(0, Solution.applyUniqueOperations(-1, setThenClear), "all set operations followed by all clear operations");
    }

    private static void testSignBit() {
        assertEquals(Integer.MIN_VALUE, Solution.applyUniqueOperations(0, new int[] {63}), "set bit 31");
        assertEquals(0, Solution.applyUniqueOperations(Integer.MIN_VALUE, new int[] {31}), "clear bit 31");
    }

    private static void testInputIsNotMutated() {
        int[] operations = {34, 7, 34, 39, 2};
        int[] original = operations.clone();
        Solution.applyUniqueOperations(123, operations);
        assertTrue(Arrays.equals(original, operations), "operations array was mutated");
    }

    private static void testStableIndependentInvocations() {
        int[] operations = {33, 1, 33};
        assertEquals(0, Solution.applyUniqueOperations(0, operations), "first invocation");
        assertEquals(0, Solution.applyUniqueOperations(0, operations), "repeated invocation");
        assertEquals(2, Solution.applyUniqueOperations(2, new int[0]), "state leaked between invocations");
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + ": expected " + expected + " but was " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
"},{"id":"cap-v2-binary_and_bitwise-java-repair-02","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testEmptyData();
        testKnownFingerprints();
        testNonAdjacentDuplicates();
        testUnsignedByteValues();
        testEveryByteValueAndRange();
        testInputIsNotMutated();
        testStableInvocations();
    }

    private static void testEmptyData() {
        assertEquals(0, Solution.fingerprintDistinctBytes(new byte[0]), "empty data");
    }

    private static void testKnownFingerprints() {
        assertEquals(0xABAB, Solution.fingerprintDistinctBytes(new byte[] {(byte) 0xAB}), "single byte");
        assertEquals(0xABAB, Solution.fingerprintDistinctBytes(new byte[] {(byte) 0xAB, (byte) 0xAB}), "adjacent duplicate");
        assertEquals(0x0A0A, Solution.fingerprintDistinctBytes(new byte[] {1, 2}), "two distinct bytes");
    }

    private static void testNonAdjacentDuplicates() {
        assertEquals(0x0A0A, Solution.fingerprintDistinctBytes(new byte[] {1, 2, 1}), "non-adjacent duplicate");
        assertEquals(0x0A0A, Solution.fingerprintDistinctBytes(new byte[] {0, 1, 0, 2}), "zero duplicated non-adjacently");
        assertEquals(0x0A0A, Solution.fingerprintDistinctBytes(new byte[] {1, 2, 1, 2, 1}), "multiple separated duplicates");
    }

    private static void testUnsignedByteValues() {
        assertEquals(0xFFFF, Solution.fingerprintDistinctBytes(new byte[] {(byte) 0xFF}), "unsigned 255");
        assertEquals(0x7F7F, Solution.fingerprintDistinctBytes(new byte[] {(byte) 0xFF, (byte) 0x80}), "unsigned high byte values");
    }

    private static void testEveryByteValueAndRange() {
        byte[] data = new byte[512];
        for (int i = 0; i < 256; i++) {
            data[i] = (byte) i;
            data[256 + i] = (byte) i;
        }
        int actual = Solution.fingerprintDistinctBytes(data);
        int expected = specificationFingerprint(data);
        assertEquals(expected, actual, "all unsigned byte values with separated duplicates");
        assertTrue(actual >= 0 && actual <= 65535, "fingerprint is outside the unsigned 16-bit range");
    }

    private static void testInputIsNotMutated() {
        byte[] data = {0, -1, 3, -128, 3, 0};
        byte[] original = data.clone();
        Solution.fingerprintDistinctBytes(data);
        assertTrue(Arrays.equals(original, data), "input data was mutated");
    }

    private static void testStableInvocations() {
        byte[] data = {1, 2, 1};
        assertEquals(0x0A0A, Solution.fingerprintDistinctBytes(data), "first invocation");
        assertEquals(0x0A0A, Solution.fingerprintDistinctBytes(data), "repeated invocation");
        assertEquals(0, Solution.fingerprintDistinctBytes(new byte[0]), "state leaked between invocations");
    }

    private static int specificationFingerprint(byte[] data) {
        boolean[] seen = new boolean[256];
        int fingerprint = 0;
        for (byte value : data) {
            int unsigned = value & 0xFF;
            if (seen[unsigned]) {
                continue;
            }
            seen[unsigned] = true;
            fingerprint = ((fingerprint << 3) | (fingerprint >>> 13)) & 0xFFFF;
            fingerprint ^= (unsigned << 8) | unsigned;
        }
        return fingerprint;
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + ": expected " + expected + " but was " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
"},{"id":"cap-v2-callbacks_and_events-java-generation-01","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testEmptyDispatch();
        testOrderAndAcknowledgementResults();
        testDefensiveMessageCopies();
        testDedicatedAcknowledgements();
        testResultIsolationAndInputNonMutation();
    }

    private static void testEmptyDispatch() {
        int[] calls = {0};
        Solution.Handler handler = (message, acknowledgement) -> calls[0]++;
        boolean[] first = Solution.dispatch(new byte[0][], handler);
        boolean[] second = Solution.dispatch(new byte[0][], handler);
        assertEquals(0, first.length, "empty result length");
        assertEquals(0, calls[0], "handler called for empty input");
        assertTrue(first != second, "empty dispatches must return newly allocated arrays");
    }

    private static void testOrderAndAcknowledgementResults() {
        byte[][] messages = {{10}, {20}, {30}, {40}};
        int[] call = {0};
        Solution.Handler handler = (message, acknowledgement) -> {
            int index = call[0]++;
            assertEquals((index + 1) * 10, message[0] & 0xFF, "dispatch order");
            if (index == 0 || index == 3) {
                acknowledgement.complete();
            }
            if (index == 3) {
                acknowledgement.complete();
                acknowledgement.complete();
            }
        };

        boolean[] result = Solution.dispatch(messages, handler);
        assertEquals(4, call[0], "handler invocation count");
        assertBooleans(new boolean[] {true, false, false, true}, result, "acknowledgement results");
    }

    private static void testDefensiveMessageCopies() {
        byte[] shared = {1, 2};
        byte[][] messages = {shared, shared};
        byte[][] delivered = new byte[2][];
        int[] call = {0};

        boolean[] result = Solution.dispatch(messages, (message, acknowledgement) -> {
            int index = call[0]++;
            delivered[index] = message;
            if (index == 0) {
                message[0] = 99;
                message[1] = 98;
            } else {
                assertBytes(new byte[] {1, 2}, message, "mutation from prior callback reached next callback");
            }
            acknowledgement.complete();
        });

        assertBooleans(new boolean[] {true, true}, result, "defensive-copy acknowledgements");
        assertBytes(new byte[] {1, 2}, shared, "source message was mutated");
        assertTrue(delivered[0] != shared && delivered[1] != shared, "callback received an input array directly");
        assertTrue(delivered[0] != delivered[1], "callbacks shared delivered message storage");
    }

    private static void testDedicatedAcknowledgements() {
        Solution.Acknowledgement[] acknowledgements = new Solution.Acknowledgement[3];
