public class SolutionTest {
    public static void main(String[] args) {
        testEmptyPipelineCopiesInitialState();
        testPipelineOrderAndCopyBoundaries();
        testMissingResponseThrowsAndStopsPipeline();
        testSecondResponseThrowsImmediately();
        testUnhandledSecondResponseThrows();
        testInvocationAndReturnIsolation();
    }

    private static void testEmptyPipelineCopiesInitialState() {
        byte[] initial = {1, 2, 3};
        byte[] result = Solution.runPipeline(initial, new Solution.Transformer[0]);
        assertBytes(new byte[] {1, 2, 3}, result, "empty pipeline result");
        assertTrue(result != initial, "empty pipeline returned the initial array directly");
        result[0] = 99;
        assertBytes(new byte[] {1, 2, 3}, initial, "returned array shared storage with initial state");
    }

    private static void testPipelineOrderAndCopyBoundaries() {
        byte[] initial = {1, 2};
        byte[][] snapshots = new byte[3][];
        byte[][] responses = new byte[3][];
        Solution.Responder[] responders = new Solution.Responder[3];
        int[] step = {0};

        Solution.Transformer[] transformers = {
            (snapshot, responder) -> {
                assertEquals(0, step[0]++, "first transformer order");
                snapshots[0] = snapshot;
                responders[0] = responder;
                assertBytes(new byte[] {1, 2}, snapshot, "first snapshot");
                snapshot[0] = 9;
                responses[0] = new byte[] {3, 4};
                responder.respond(responses[0]);
                responses[0][0] = 99;
            },
            (snapshot, responder) -> {
                assertEquals(1, step[0]++, "second transformer order");
                snapshots[1] = snapshot;
                responders[1] = responder;
                assertBytes(new byte[] {3, 4}, snapshot, "response was not copied at respond time");
                snapshot[1] = 5;
                responses[1] = snapshot;
                responder.respond(snapshot);
                snapshot[0] = 88;
                snapshot[1] = 88;
            },
            (snapshot, responder) -> {
                assertEquals(2, step[0]++, "third transformer order");
                snapshots[2] = snapshot;
                responders[2] = responder;
                assertBytes(new byte[] {3, 5}, snapshot, "accepted response shared mutable storage");
                responses[2] = new byte[] {6, 7};
                responder.respond(responses[2]);
            }
        };

        byte[] result = Solution.runPipeline(initial, transformers);
        assertEquals(3, step[0], "transformer invocation count");
        assertBytes(new byte[] {6, 7}, result, "pipeline result");
        assertBytes(new byte[] {1, 2}, initial, "initial state was mutated");
        assertTrue(snapshots[0] != initial, "first callback received the initial array directly");
        assertTrue(snapshots[1] != responses[0], "second snapshot shared the first response array");
        assertTrue(snapshots[2] != responses[1], "third snapshot shared the second response array");
        assertTrue(responders[0] != responders[1] && responders[1] != responders[2] && responders[0] != responders[2],
                "transformers did not receive dedicated responders");
        assertTrue(result != responses[2], "returned array shared the final response array");
        responses[2][0] = 42;
        assertBytes(new byte[] {6, 7}, result, "final response alias changed returned state");
    }

    private static void testMissingResponseThrowsAndStopsPipeline() {
        int[] calls = {0};
        Solution.Transformer[] transformers = {
            (snapshot, responder) -> calls[0]++,
            (snapshot, responder) -> {
                calls[0]++;
                responder.respond(new byte[] {9});
            }
        };

        expectIllegalState(() -> Solution.runPipeline(new byte[] {1}, transformers), "missing response");
        assertEquals(1, calls[0], "pipeline continued after a transformer returned without responding");
    }

    private static void testSecondResponseThrowsImmediately() {
        boolean[] caughtInsideCallback = {false};
        byte[] result = Solution.runPipeline(new byte[] {0}, new Solution.Transformer[] {
            (snapshot, responder) -> {
                responder.respond(new byte[] {7});
                try {
                    responder.respond(new byte[] {8});
                    throw new AssertionError("second response did not throw");
                } catch (IllegalStateException expected) {
                    caughtInsideCallback[0] = true;
                }
            }
        });
        assertTrue(caughtInsideCallback[0], "second response was not rejected immediately");
        assertBytes(new byte[] {7}, result, "second response replaced the first response");
    }

    private static void testUnhandledSecondResponseThrows() {
        expectIllegalState(() -> Solution.runPipeline(new byte[] {0}, new Solution.Transformer[] {
            (snapshot, responder) -> {
                responder.respond(new byte[] {1});
                responder.respond(new byte[] {2});
            }
        }), "unhandled second response");
    }

    private static void testInvocationAndReturnIsolation() {
        byte[] initial = {4};
