        assertBytes(new byte[] {5}, second, "earlier returned-array mutation affected a later invocation");
        assertBytes(new byte[] {4}, initial, "pipeline mutated initial input");
        assertBytes(new byte[] {5}, suppliedResponse, "pipeline mutated a supplied response");
    }

    private static void expectIllegalState(Runnable action, String message) {
        try {
            action.run();
            throw new AssertionError(message + ": expected IllegalStateException");
        } catch (IllegalStateException expected) {
            // Expected.
        }
